           if not t.is_water and not t.is_mountain
           and t.feature != 'FEATURE_GEOTHERMAL_FISSURE'
           and (x,y) != cc and hex_distance(x,y,cc[0],cc[1]) <= 3]
    interesting = set()
    for (x,y) in vdt:
        for n in get_neighbors(x,y):
